using SlideRule.Codebase;
using SlideRule.Rendering;
using SlideRule.Tests.Extraction;
using SlideRule.Tests.TestSupport;

namespace SlideRule.Tests.Rendering;

/// <summary>
///     Spec fixtures the context-rendering suites share. A scene two renderer suites are pinned
///     against is held once: the pins only mean what they say while the input is literally the same.
/// </summary>
internal static class ContextFixtures
{
    /// <summary>
    ///     The one file a source-only package ships, as the containment scenes compile it. The
    ///     <c>&lt;auto-generated /&gt;</c> banner is what makes the extractor read it as generated code,
    ///     which is the fact both scenes — the synthesized one and the restored one — are placed against.
    /// </summary>
    internal const string ShimSource =
        """
        // <auto-generated />
        namespace Contoso.Shims
        {
            internal static class XShim
            {
            }
        }
        """;

    /// <summary>
    ///     The solution directory every scene is placed inside. A card may only land inside it, so the scenes'
    ///     codebases declare their files under it. The path is built and never created.
    /// </summary>
    // Declared above every codebase, because static initializers run in declaration order and theirs read it.
    internal static readonly string SolutionDirectory = Path.Combine(TestTempRoot.For("context-fixtures"), "sln");

    /// <summary>
    ///     The one-file Web codebase the scenes below are placed against: a single controller under
    ///     <c>src/MyApp.Web</c>, which is the directory both suites expect a Web card to land in.
    /// </summary>
    internal static readonly CodebaseModel WebCodebase = CompilationFactory.Extract("MyApp.Web",
        (Site("src", "MyApp.Web", "HomeController.cs"), "namespace MyApp.Web; public class HomeController {}"));

    /// <summary>The absolute path of a file under <see cref="SolutionDirectory" />, from its segments.</summary>
    internal static string Site(params string[] segments)
    {
        return Path.Combine([SolutionDirectory, .. segments]);
    }

    /// <summary>
    ///     A placed path as a pin reads it: relative to <see cref="SolutionDirectory" /> and forward-slashed. Null
    ///     stays null, so a skipped card fails its pin as itself.
    /// </summary>
    internal static string? Relative(string? path)
    {
        return Relative(SolutionDirectory, path);
    }

    /// <summary>
    ///     The same, against a root of the caller's own — for a scene whose solution directory is not this
    ///     file's, such as one placing a card beside a package folder outside the checkout.
    /// </summary>
    internal static string? Relative(string baseDirectory, string? path)
    {
        return path is null ? null : PathFormat.Relative(baseDirectory, path);
    }

    /// <summary>
    ///     A Web layer with one bare-subject Enforce rule anchored on it — saying what it is for when
    ///     given a purpose, which is the sentence the card lede carries.
    /// </summary>
    internal static Action<Arch> WebLayer(string? purpose = null)
    {
        return arch =>
        {
            Layer web = arch.Layer("Web", "MyApp.Web.*");
            if (purpose is not null) web.Purpose(purpose);
            arch.Rule("layering/web-not-billing")
                .Enforce(web.MustNotReference(arch.Namespace("MyApp.Legacy.Billing.*")))
                .Because("Web reaches billing only through the facade.");
        };
    }

    /// <summary>
    ///     The mirror of <see cref="WebLayer" />: a Billing layer with one bare-subject Enforce rule
    ///     anchored on it.
    /// </summary>
    internal static void BillingLayer(Arch arch)
    {
        Layer billing = arch.Layer("Billing", "MyApp.Legacy.Billing.*");
        arch.Rule("layering/billing-not-web")
            .Enforce(billing.MustNotReference(arch.Namespace("MyApp.Web.*")))
            .Because("Billing is downstream of the web layer.");
    }
}
